INSERT INTO public.schemes (id, slug, ulb_code, ulb_name, department, pillar, category, category_label, scheme_code, name, vernacular_name, description, benefit_amount, benefit_type, grant_amount, deadline, application_deadline, cutoff, income_limit, income_limit_formatted, domicile_years, resolution_no, gazette_gr_number, gazette_date, source_url, ward_office_id, required_documents, staple_order, official_form_name, official_form_url, is_active, created_at, updated_at, desk_type, name_i18n, description_i18n, cutoff_i18n, window_opens_at, verification_status, last_verified_at, source_hash, source_doc_id, eligibility_text, eligibility_text_mr, application_mode, apply_url, how_to_apply)
VALUES
  ('d70a6d8f-4f67-45a8-8991-221089da7a5e', 'pmc-ambedkar-student-hostel', 'PMC-001', 'Pune Municipal Corporation', 'Social Welfare Department', 'EDUCATION', 'education', 'Education', 'PMC_AMBEDKAR_STUDENT_HOSTEL', 'Bharat Ratna Dr. Babasaheb Ambedkar Student Hostel', '{"mr":"unknown"}'::jsonb, 'A student hostel established by the Pune Municipal Corporation in 1968 with a capacity of 400 students, providing accommodation for students from outside Pune city so they can pursue higher education in Pune. Admitted students receive a monthly DBT allowance of ₹2,150 from Pune Municipal Corporation for meal expenses, directly deposited into their bank accounts.', 'Rs. 2,150', 'One-time Direct Bank Transfer (DBT)', 0, 'Apply online between July and August', NULL, 'Admission is based on a merit list prepared considering the marks obtained in the last qualifying examination, with preference given to students from engineering, medical, science, agriculture, arts, and commerce fields.', 100000, NULL, NULL, NULL, NULL, NULL, 'https://webadmin.pmc.gov.in/bharat-ratna-dr-babasaheb-ambedkar-student-hostel', NULL, '["Caste certificate","Income certificate issued by the Tehsildar","Required mark sheets","Ration card","School leaving certificate","Original bonafide certificate from the admitted college with an official stamp","Aadhaar Card","Xerox copy of bank passbook","Fee receipt and security deposit challan for previously admitted students","Three recent passport-sized photographs"]'::jsonb, '["1. Application form","Caste certificate","Income certificate issued by the Tehsildar","Required mark sheets","Ration card","School leaving certificate","Original bonafide certificate from the admitted college with an official stamp","Aadhaar Card","Xerox copy of bank passbook","Fee receipt and security deposit challan for previously admitted students","Three recent passport-sized photographs"]'::jsonb, NULL, NULL, TRUE, '2026-10-04T10:32:17.32177+00:00', '2026-10-04T10:32:17.32177+00:00', 'EDU_DBT', '{}'::jsonb, '{}'::jsonb, '{}'::jsonb, NULL, 'verified', '2026-10-04T10:58:10.029+00:00', '4de698ec555185142bdc6cdcbc14060abe96c9bf5f4f1e7f5067ee5756a0d00b', NULL, 'The hostel primarily provides admission to students belonging to backward castes and tribes, as well as those whose parents'' total annual income does not exceed ₹1 lakh.
