INSERT INTO public.scheme_faqs (id, scheme_id, question, answer, language_code, display_order, status, created_at, updated_at, published_at)
VALUES
  ('265568c4-2124-4e4b-b83b-da077ae8136f', 'a3333333-3333-3333-3333-333333333333', 'Which documents are required?', 'Copy of Yellow (BPL) or Orange (APL Low-Income) ration card; Tahsildar Family Income Certificate (under Rs. 1,60,000); head of family and patient Aadhaar cards; proof of 3 years residence in PMC limits (property tax or election card); doctor''s treatment estimation certificate or admission advice; and two passport-size photographs of the patient.', 'en', 4, 'PUBLISHED', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00'),
  ('293b5481-2ef9-4e64-b4a6-35c6cbbe2ad5', 'a2222222-2222-2222-2222-222222222222', 'What is this scheme?', 'One-time cash assistance grant for Pune students who cleared Class 12 (HSC) and enrolled into higher degree programs (Engineering, Medical, Commerce, Science, Arts, IT).', 'en', 1, 'PUBLISHED', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00'),
  ('2a6cc841-6c4b-4db2-b536-b9a44f335207', 'a3333333-3333-3333-3333-333333333333', 'Who is eligible?', 'Family annual income below Rs. 1,60,000. Resident within Pune Municipal Corporation limits. Yellow or Orange ration card holder. Annual membership renewal required.', 'en', 2, 'PUBLISHED', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00'),
  ('31f2c0fd-e538-4616-8453-eec199b94c56', 'a5555555-5555-5555-5555-555555555555', 'Who is eligible?', 'Street vendor selling in Pune municipal limits (vegetables, fruit, flowers, produce, dairy). Holds a Vending Certificate or Identity Card, or appears in the ward vendor survey, or has a recommendation letter from the Town Vending Committee or ward office. The next loan tranche is available only after repaying the previous one.', 'en', 2, 'PUBLISHED', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00'),
  ('3931c84f-d67e-40b9-a7d5-2d81b4b7605b', 'a1111111-1111-1111-1111-111111111111', 'पात्रता निकष काय आहेत?', 'इयत्ता 10 वी (एसएससी) उत्तीर्ण व 11 वी किंवा मान्यताप्राप्त डिप्लोमा अभ्यासक्रमात प्रवेश; खुल्या प्रवर्गासाठी किमान 80% गुण; पुणे महानगरपालिका हद्दीत रहिवासी; राष्ट्रीयीकृत बँकेत आधार जोडलेले खाते.', 'mr', 2, 'PUBLISHED', '2026-10-04T07:21:03.939149+00:00', '2026-10-04T07:22:55.873809+00:00', '2026-10-04T07:22:55.873809+00:00'),
  ('5d3b414d-2afe-4a5e-a38c-1ce7742e607d', 'a6666666-6666-6666-6666-666666666666', 'How much is the benefit?', 'Rs. 10,000 to Rs. 20,000 as financial assistance toward course fees.', 'en', 3, 'PUBLISHED', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00'),
  ('64a8844d-a78e-400c-add0-55dd4e1e5b92', 'a6666666-6666-6666-6666-666666666666', 'What is the application deadline?', 'The published deadline for this scheme is October 31, 2026. Confirm the current window at the ward office before travelling.', 'en', 5, 'PUBLISHED', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00'),
  ('715e61b0-eb60-4cb7-833d-84e979b7f12f', 'a1111111-1111-1111-1111-111111111111', 'What is this scheme?', 'Financial assistance for meritorious students who passed Class 10 (SSC) and are admitted to Junior College (Class 11) or a recognised diploma course within Pune municipal limits.', 'en', 1, 'PUBLISHED', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00'),
  ('75b3860d-a075-4dfb-bd1e-751fe7b52907', 'a6666666-6666-6666-6666-666666666666', 'Where do I submit the application?', 'Submit at the Kothrud - Bawdhan Ward Office No. 14, Counter No. 3 (Samaj Vikas DBT Desk).', 'en', 6, 'PUBLISHED', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00'),
  ('78660610-310a-4d87-a3e3-3cc8bd271448', 'a2222222-2222-2222-2222-222222222222', 'How much is the benefit?', 'Rs. 25,000, paid as a one-time Direct Bank Transfer (DBT) to the student''s bank account.', 'en', 3, 'PUBLISHED', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00'),
  ('86422eaf-4b5b-4a97-a6d2-34ada49b3745', 'a6666666-6666-6666-6666-666666666666', 'What is this scheme?', 'Financial assistance toward technical training, nursing diplomas, and computer certification fees for female students residing in Pune municipal corporation wards.', 'en', 1, 'PUBLISHED', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00'),
  ('89f1a79d-d6c3-41bf-aeb1-d781eacea9da', 'a2222222-2222-2222-2222-222222222222', 'Who is eligible?', 'Passed Class 12 (HSC) and admitted to a degree course. Minimum 80% marks in Class 12 (open category); 70% for backward-class students of state-government or PMC-aided schools; 65% for children of waste-pickers, construction or unorganised workers; 45% for students with more than 40% disability. Resident within Pune Municipal Corporation limits. Bank account in a nationalised bank, linked to Aadhaar.', 'en', 2, 'PUBLISHED', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00'),
  ('90695c33-93f7-4d67-bda8-e63c6a1015cb', 'a5555555-5555-5555-5555-555555555555', 'Which documents are required?', 'Vendor identification card (vending certificate or ward survey slip); bank passbook copy with active UPI QR linkage; Aadhaar card copy; and a recommendation letter from the local ward hawkers committee or market supervisor.', 'en', 4, 'PUBLISHED', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00'),
  ('96208b28-40c0-4f8a-9174-dd628caa64d6', 'a1111111-1111-1111-1111-111111111111', 'What is the application deadline?', 'The published deadline for this scheme is October 31, 2026. Confirm the current window at the ward office before travelling.', 'en', 5, 'PUBLISHED', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00'),
  ('a763aa64-dfab-4239-bc75-27c18750ed36', 'a6666666-6666-6666-6666-666666666666', 'Who is eligible?', 'Girl student enrolled in an ITI, polytechnic, nursing or computer diploma course. Family annual income under Rs. 2,50,000 (waived for orphans). Resident within Pune Municipal Corporation limits.', 'en', 2, 'PUBLISHED', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00'),
  ('a9fea605-ef1a-453a-8ec0-918c06e648fc', 'a3333333-3333-3333-3333-333333333333', 'Where do I submit the application?', 'Submit at the Kothrud - Bawdhan Ward Office No. 14 health desk. The official form is available from the SGAY PMC portal.', 'en', 6, 'PUBLISHED', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00'),
  ('aa8acbf3-82c9-4474-861b-4f7b5bb9f1b7', 'a1111111-1111-1111-1111-111111111111', 'ही योजना काय आहे?', 'पुणे महानगरपालिका हद्दीतील इयत्ता 10 वी (एसएससी) उत्तीर्ण व अकरावी किंवा मान्यताप्राप्त डिप्लोमा अभ्यासक्रमात प्रवेश घेतलेल्या गुणवंत विद्यार्थ्यांसाठी आर्थिक सहाय्य.', 'mr', 1, 'PUBLISHED', '2026-10-04T07:21:03.939149+00:00', '2026-10-04T07:22:55.873809+00:00', '2026-10-04T07:22:55.873809+00:00'),
  ('ad166aa2-fe02-4913-a34d-de533cd0562b', 'a1111111-1111-1111-1111-111111111111', 'How much is the benefit?', 'Rs. 15,000, paid as a one-time Direct Bank Transfer (DBT) to the student''s bank account.', 'en', 3, 'PUBLISHED', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00'),
  ('b572621b-a926-4d33-bd9e-06726a8918a7', 'a3333333-3333-3333-3333-333333333333', 'What is this scheme?', 'Shahari Garib Arogya Yojana (SGAY) provides 100% free treatment at municipal civic hospitals and 50% direct concession on CGHS billing rates across 50+ empaneled private hospitals in Pune. It covers general inpatient hospitalization, nephrology dialysis, and chemotherapy.', 'en', 1, 'PUBLISHED', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00'),
  ('c0f7e566-5e03-491f-8175-0d062632026d', 'a6666666-6666-6666-6666-666666666666', 'Which documents are required?', 'Admission fee receipt from an accredited Technical or ITI institute; Class 10 or 12 marksheet copy; Tahsildar income certificate; student bank passbook copy; and student Aadhaar card.', 'en', 4, 'PUBLISHED', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00'),
  ('c195500d-3024-48e7-ba72-71a859edfe43', 'a1111111-1111-1111-1111-111111111111', 'Where do I submit the application?', 'Submit at the Kothrud - Bawdhan Ward Office No. 14, Counter No. 3 (Samaj Vikas DBT Desk), Monday to Friday, 10:30 AM to 03:30 PM. The official form is available from the PMC DBT portal.', 'en', 6, 'PUBLISHED', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00'),
  ('c6a577cb-4f1b-4aa7-b8cb-ba190340017f', 'a2222222-2222-2222-2222-222222222222', 'Which documents are required?', 'Attested copy of Class 12 (HSC) marksheet; degree college bonafide certificate or first-term fee receipt; Tahsildar Family Income Certificate; student bank passbook copy; student Aadhaar card; and proof of 3 years Pune domicile.', 'en', 4, 'PUBLISHED', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00'),
  ('c866f6e2-49df-43d8-9710-4a993a43d1ce', 'a5555555-5555-5555-5555-555555555555', 'What is this scheme?', 'PM SVANidhi provides working capital loans to street vendors who sell fresh farm produce, fruits, vegetables, and dairy in Pune municipal weekly markets (Athawadi Bajar) and roadside haats.', 'en', 1, 'PUBLISHED', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00'),
  ('cf728d5c-b708-4167-b9b5-74a7ffb95b28', 'a1111111-1111-1111-1111-111111111111', 'Which documents are required?', 'Attested copy of Class 10 (SSC) marksheet; Tahsildar Family Income Certificate (FY 2025-26); student bank passbook copy with active IFSC; student Aadhaar card; current-year Junior College or Diploma fee receipt or bonafide; proof of 3-year continuous residence in PMC limits; and a signed Small Family Undertaking Declaration.', 'en', 4, 'PUBLISHED', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00'),
  ('d89e5f5a-257e-4bca-a017-4ff04c945044', 'a2222222-2222-2222-2222-222222222222', 'Where do I submit the application?', 'Submit at the Kothrud - Bawdhan Ward Office No. 14, Counter No. 3 (Samaj Vikas DBT Desk). The official form is available from the PMC DBT portal.', 'en', 5, 'PUBLISHED', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00'),
  ('e37e224f-e200-4a1b-bc18-10c08236acfb', 'a1111111-1111-1111-1111-111111111111', 'Who is eligible?', 'Passed Class 10 (SSC) and admitted to Class 11 or a recognised diploma course. Minimum 80% marks in Class 10 (open category); 70% for backward-class students of state-government or PMC-aided schools; 65% for children of waste-pickers, construction or unorganised workers; 45% for students with more than 40% disability. Resident within Pune Municipal Corporation limits. Bank account in a nationalised bank, linked to Aadhaar.', 'en', 2, 'PUBLISHED', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00'),
  ('ee28997e-675e-4283-b93d-436887afd3a7', 'a5555555-5555-5555-5555-555555555555', 'What is the application deadline?', 'This scheme is open round the year.', 'en', 5, 'PUBLISHED', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00'),
  ('eec43f19-78d1-4198-92bf-a28d738ac85f', 'a3333333-3333-3333-3333-333333333333', 'How much is the benefit?', 'Rs. 1,00,000 to Rs. 2,00,000 in medical cover, with 100% free treatment at municipal hospitals and 50% concession at empaneled private hospitals.', 'en', 3, 'PUBLISHED', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00'),
  ('f630b1ab-9c28-45a1-b21d-a71685fd29b0', 'a5555555-5555-5555-5555-555555555555', 'How much is the loan?', '1st tranche: Rs. 10,000; 2nd tranche: Rs. 20,000; 3rd tranche: Rs. 50,000.', 'en', 3, 'PUBLISHED', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00'),
  ('f6e77fe6-09c6-4433-9eb5-0a34260acc8a', 'a3333333-3333-3333-3333-333333333333', 'What is the application deadline?', 'This scheme is open round the year with an annual membership. Confirm renewal at the ward office.', 'en', 5, 'PUBLISHED', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00', '2026-10-04T07:17:12.067692+00:00')
INSERT INTO public.peer_intel_reviews (id, scheme_id, ward_office_id, author, role, counter, tip, friction_tag, severity_level, helpful_count, verified_by_moderator, created_at)
VALUES
  ('09850980-a1be-45e7-8490-362ea95d3a43', 'a3333333-3333-3333-3333-333333333333', 'e2222222-2222-2222-2222-222222222222', 'Kavita Deshmukh', 'Patient Family Member', 'Ward 14 Health Desk', 'The hospital''s Medical Social Worker (MSW) must sign the treatment estimate quotation before you come to Counter 1. The municipal health clerk verifies the doctor''s seal.', 'MSW_SIGNATURE', 'MEDIUM', 37, TRUE, '2026-10-03T18:37:54.615387+00:00'),
  ('23a95038-c580-4c93-be91-04a6c3f1cd00', 'a3333333-3333-3333-3333-333333333333', 'e2222222-2222-2222-2222-222222222222', 'Dr. Anand Kulkarni', 'Hospital Social Worker', 'Ward 14 Health Desk', 'Annual membership fee is Rs. 200. Keep exact cash ready as the counter does not always have digital UPI QR scanners operational.', 'UNOFFICIAL_FEE', 'MEDIUM', 22, TRUE, '2026-10-03T22:07:29.407244+00:00'),
  ('2455bc89-d8ce-432b-abe1-e585e56cb379', 'a1111111-1111-1111-1111-111111111111', 'e1111111-1111-1111-1111-111111111111', 'Rahul Shinde', 'Parent Applicant', 'Kothrud Ward 14, Counter 3', 'Make sure to bring 2 physical passport size photos attached with a paperclip. The clerk asked for them even though it was not explicitly stated on the main notice. Other than that, file acceptance took 10 minutes.', 'PHOTOCOPY_DEMAND', 'MEDIUM', 28, TRUE, '2026-10-03T18:37:54.615387+00:00'),
  ('73b86349-c920-4601-9725-8a1134ceed68', 'a1111111-1111-1111-1111-111111111111', NULL, 'Test Citizen', 'Citizen Applicant', 'Ward 14: Kothrud - Bawdhan', 'Bring two passport-size photos clipped to the form; the desk keeps them with the application packet.', NULL, 'MEDIUM', 1, TRUE, '2026-10-04T08:58:52.044761+00:00'),
  ('aadb7f5a-06d5-4aed-9c90-d5d09716e6a3', 'a1111111-1111-1111-1111-111111111111', 'e1111111-1111-1111-1111-111111111111', 'Dnyaneshwar Jadhav', 'Student Beneficiary', 'Kothrud Ward 14, Counter 3', 'Online DigiLocker printout of the Tahsildar certificate is fully accepted as long as the 16-digit barcoded verification number is dark and clearly legible for scanning.', 'DIGILOCKER_OK', 'MEDIUM', 19, TRUE, '2026-10-03T18:37:54.615387+00:00'),
  ('ca1b1bd8-a731-41ef-b70c-315ad22df29b', 'a2222222-2222-2222-2222-222222222222', 'e1111111-1111-1111-1111-111111111111', 'Prashant Kadam', 'Student Beneficiary', 'Kothrud Ward 14, Counter 3', 'Ensure your college bonafide certificate mentions the academic year 2026-27 clearly. They will not accept previous year receipts.', 'TIMING', 'MEDIUM', 14, TRUE, '2026-10-03T22:07:29.407244+00:00'),
  ('d8496207-4abf-4cc6-9170-2198cbef45f2', 'a1111111-1111-1111-1111-111111111111', 'e1111111-1111-1111-1111-111111111111', 'Sunita More', 'Community Volunteer (Samaj Sevak)', 'Kothrud Ward 14, Counter 3', 'If you have an older Syndicate Bank or Allahabad Bank passbook, make sure the IFSC code is updated to the merged parent bank (Canara Bank / Indian Bank). The PMC DBT payment gateway will bounce the transaction if an obsolete code is submitted.', 'IFSC_MERGER', 'MEDIUM', 45, TRUE, '2026-10-03T18:37:54.615387+00:00'),
  ('dadeb661-34e8-41d7-9db7-f27b02eae741', 'a5555555-5555-5555-5555-555555555555', 'e4444444-4444-4444-4444-444444444444', 'Tukaram Gaikwad', 'Vegetable Vendor (Kothrud Market)', 'Ward 14, Counter 5', 'Link your Google Pay or PhonePe merchant QR to the bank account before applying.', 'PHOTOCOPY_DEMAND', 'MEDIUM', 30, TRUE, '2026-10-03T22:07:29.407244+00:00'),
  ('eb785ed0-a4a6-4378-95db-85e80b0c5f7c', 'a6666666-6666-6666-6666-666666666666', 'e1111111-1111-1111-1111-111111111111', 'Priya Bhosale', 'Nursing Student', 'Ward 14, Counter 3', 'Ensure your institute fee receipt has the official GST or registration stamp of the ITI/college, otherwise the clerk asks for a bonafide letter.', 'PHOTOCOPY_DEMAND', 'MEDIUM', 17, TRUE, '2026-10-03T22:07:29.407244+00:00')
