  ('c2eebcde-6a2c-41f6-8e59-9d1892efcb66', 'pmc-chs-health-service', 'PMC-001', 'Pune Municipal Corporation', 'आरोग्य विभाग, पुणे महानगरपालिका', 'HEALTHCARE', 'healthcare', 'Healthcare', 'PMC_CHS_HEALTH_SERVICE', 'Contributory Health Service - CHS of Pune Municipal Corporation', '{"mr":"अंशदायी वैद्यकीय सहाय्य योजना"}'::jsonb, 'The Contributory Health Service (CHS) scheme provides healthcare coverage to Pune Municipal Corporation employees, retirees, and Education Board/PMPEL department staff. Members contribute 1% of basic salary plus Dearness Allowance monthly. Treatment at empanelled hospitals is covered up to ₹10 lakh with bills paid directly by PMC; for non-empanelled hospitals, ₹10 lakh plus the difference is covered.', 'Rs. 10,00,000', 'One-time Direct Bank Transfer (DBT)', 0, NULL, NULL, 'दर माह वेतनांतून/पेन्शन मधून बेसिक + महागाई भत्ताच्या १% प्रमाणे वर्गणी', NULL, NULL, NULL, '३४६ दि.-१२/१२/२०२५', NULL, NULL, 'https://webadmin.pmc.gov.in/sites/default/files/circular/Contributory%20Health%20Service%20-%20CHS%20of%20Pune%20Municipal%20Corporation%20_1.pdf', NULL, '["Aadhaar Card"]'::jsonb, '["1. Application form","Aadhaar Card"]'::jsonb, NULL, NULL, TRUE, '2026-10-04T10:46:53.123877+00:00', '2026-10-04T10:46:53.123877+00:00', 'HEALTH', '{}'::jsonb, '{}'::jsonb, '{}'::jsonb, NULL, 'verified', '2026-10-04T10:58:10.029+00:00', '54ae81a65ee7c17427c59499d75f70c30b1df0deeeade58e238ca83bf66c3afc', NULL, 'पुणे महानगरपालिकेच्या सेवक/सेविका, सेवा निवृत्त सेवक/सेविका, शिक्षण मंडळ व पी.एम.पी.एम.एल विभागाकडील सेवक/सेविका यांना योजनेचे सभासदत्व देण्यात येते.
२००५ नंतर ज्या पुणे मनपा अधिकारी/सेवकांची नेमणूक आहे व त्यांना पेन्शन योजना लागू नाही अशा अधिकारी व कर्मचारी यांना सेवा निवृत्तीच्या शेवटच्या वेतनातील मूळ वेतन+ महागाई भत्त्याची १% रक्कम गुणिले १ महिने अशी एकूण रक्कम आगाऊ कपात करून सभासदत्व घ्यावे लागते.', NULL, 'offline', NULL, NULL),
  ('8aeb7380-604b-45b4-b428-99f7b66f2694', 'pmc-cm-youth-training', 'PMC-001', 'Pune Municipal Corporation', 'कौशल्य, रोजगार, उद्योजकता व नाविन्यता विभाग, महाराष्ट्र शासन', 'AGRICULTURE_LIVELIHOOD', 'livelihood', 'Livelihood & Self-Employment', 'PMC_CM_YOUTH_TRAINING', 'Mukhyamantri Yuva Karya Prashikshan Yojana', '{"mr":"मुख्यमंत्री युवा कार्य प्रशिक्षण योजना"}'::jsonb, 'The Mukhyamantri Yuva Karya Prashikshan Yojana is a Maharashtra government scheme that provides 6 months of practical on-job training to unemployed youth (aged 18-35) with educational qualifications from 12th pass to post-graduate level. Registered industries and establishments provide training, and candidates receive a monthly stipend of Rs. 6,000 to Rs. 10,000 based on their educational qualification, transferred directly to their Aadhaar-linked bank account via DBT.', 'Rs. 10,000', 'One-time Direct Bank Transfer (DBT)', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'संकीणय-2024/प्र.क्र.90/व्यशि-3', NULL, NULL, 'https://webadmin.pmc.gov.in/sites/default/files/circular/%E0%A4%AA%E0%A4%B0%E0%A4%BF%E0%A4%AA%E0%A4%A4%E0%A5%8D%E0%A4%B0%E0%A4%95%20%E0%A4%AE%E0%A5%81%E0%A4%96%E0%A5%8D%E0%A4%AF%E0%A4%AE%E0%A4%82%E0%A4%A4%E0%A5%8D%E0%A4%B0%E0%A5%80%20%E0%A4%AF%E0%A5%81%E0%A4%B5%E0%A4%BE%20%E0%A4%95%E0%A4%BE%E0%A4%B0%E0%A5%8D%E0%A4%AF%20%E0%A4%AA%E0%A5%8D%E0%A4%B0%E0%A4%B6%E0%A4%BF%E0%A4%95%E0%A5%8D%E0%A4%B7%E0%A4%A3%20%E0%A4%AF%E0%A5%8B%E0%A4%9C%E0%A4%A8%E0%A4%BE.pdf', NULL, '["Aadhaar Card","Aadhaar-linked Bank Account","Educational Qualification Certificate"]'::jsonb, '["1. Application form","Aadhaar Card","Aadhaar-linked Bank Account","Educational Qualification Certificate"]'::jsonb, NULL, NULL, TRUE, '2026-10-04T10:45:39.000459+00:00', '2026-10-04T10:45:39.000459+00:00', 'EDU_DBT', '{}'::jsonb, '{}'::jsonb, '{}'::jsonb, NULL, 'verified', '2026-10-04T10:58:10.029+00:00', 'c5a81f181603964125a4dabdb3c6ba95f25b58677a2e58e627602d473fb2c00e', NULL, 'Candidate should be in the age group of 18 to 35.
Candidate should have minimum education criteria of 12th Pass/ITI/Diploma/Graduation/Post Graduation.
Candidate should be the resident of Maharashtra.
Candidate should register with Aadhar.
Candidates'' bank account should link with Aadhar.
