  ('8556d11f-189c-42a1-87ca-26f79b8def8f', 'pmc-contributory-medical-aid', 'PMC-001', 'Pune Municipal Corporation', 'आरोग्य विभाग, पुणे महानगरपालिका', 'HEALTHCARE', 'healthcare', 'Healthcare', 'PMC_CONTRIBUTORY_MEDICAL_AID', 'अंशदायी वैद्यकीय सहाय्य योजना', '{"mr":"अंशदायी वैद्यकीय सहाय्य योजना"}'::jsonb, 'PMC Health Department''s contributory medical aid scheme that reimburses medical bills for personal medical expenses of PMC employees, retired employees, Education Board and PMPEL department staff, and current/former corporators. This clarification circular (शुद्धीपत्रक) specifies that female beneficiaries may register either their husband''s name or father''s name — not both in the same financial year — with a self-declaration required.', NULL, 'One-time Direct Bank Transfer (DBT)', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'जा.क्र.एचआय/ ६०७', NULL, NULL, 'https://webadmin.pmc.gov.in/sites/default/files/circular/DocScanner%2025-Oct-2023%205-37%20pm.pdf', NULL, '["Self-declaration (स्वयंघोषणापत्र)"]'::jsonb, '["1. Application form","Self-declaration (स्वयंघोषणापत्र)"]'::jsonb, NULL, NULL, TRUE, '2026-10-04T10:45:40.506394+00:00', '2026-10-04T10:45:40.506394+00:00', 'HEALTH', '{}'::jsonb, '{}'::jsonb, '{}'::jsonb, NULL, 'verified', '2026-10-04T10:58:10.029+00:00', 'b4d47fcd282bc73430a40ed77914c8ff2529ef7bfa4f2142e9964b871f85f42c', NULL, 'पुणे महानगरपालिका सेवक/सेविका, सेवा निवृत्त सेवक/सेविका, शिक्षण मंडळ व पीएमपीएमएल विभागाकडील सेवक/सेविका, सेवा निवृत्त सेवक/सेविका, मा. आजि सभासद, व मा. माजी सभासद यांचे वैयक्तिक स्वखर्चाची वैद्यकीय परतावा बिले सादर केल्याअंतर सदर वैद्यकीय बिलांची प्रतिपूर्ती करण्यात येत आहे.', NULL, 'offline', NULL, NULL),
  ('1e43f977-d916-4313-a487-863389fc1470', 'pmc-financial-initiatives', 'PMC-001', 'Pune Municipal Corporation', 'Labour Welfare Department', 'AGRICULTURE_LIVELIHOOD', 'livelihood', 'Livelihood & Self-Employment', 'PMC_FINANCIAL_INITIATIVES', 'Financial Initiatives', '{"mr":"unknown"}'::jsonb, 'Under this Pune Municipal Corporation initiative, financial assistance of Rs. 75,000 (Rs. 22,500 from the PMC Worker''s Welfare Fund and Rs. 52,500 from the PMC general fund) is provided to the legal heirs of PMC employees who passed away while in service. The page also covers a computer loan of Rs. 25,000 at 3% interest for Class 3 & 4 employees, the Provident Fund upon retirement, and Workmen''s Compensation for accidents on duty under the Workmen''s Compensation Act of 1923.', 'Rs. 75,000', 'One-time Direct Bank Transfer (DBT)', 0, NULL, NULL, 'Application in the prescribed format within 1 year from the death of the employee', NULL, NULL, NULL, NULL, NULL, NULL, 'https://webadmin.pmc.gov.in/financial-initiatives-0', NULL, '["Application in the prescribed format (within 1 year from the death of the employee)","Original copy of the Death Certificate of the employee","Payment slip","Xerox copy of ration card","Bank Passbook Xerox"]'::jsonb, '["1. Application form","Application in the prescribed format (within 1 year from the death of the employee)","Original copy of the Death Certificate of the employee","Payment slip","Xerox copy of ration card","Bank Passbook Xerox"]'::jsonb, NULL, NULL, TRUE, '2026-10-04T10:32:15.539237+00:00', '2026-10-04T10:32:15.539237+00:00', 'EDU_DBT', '{}'::jsonb, '{}'::jsonb, '{}'::jsonb, NULL, 'verified', '2026-10-04T10:58:10.029+00:00', '873b4b4d50b5194be68389ceda72bfbd4c7f07af3cd2c90b486a5b7181993730', NULL, 'Financial assistance is provided to the legal heirs of employees who passed away while in service.
The application must be made in the prescribed format within 1 year from the death of the employee.', NULL, NULL, NULL, NULL),
  ('71e18dd7-695f-456f-a4e0-8ea6938f27f9', 'pmc-labour-welfare-fund', 'PMC-001', 'Pune Municipal Corporation', 'Labour Welfare Department', 'AGRICULTURE_LIVELIHOOD', 'livelihood', 'Livelihood & Self-Employment', 'PMC_LABOUR_WELFARE_FUND', 'Labour Welfare Fund', '{"mr":"कामगार कल्याण निधी"}'::jsonb, 'A unique fund named as Labour Welfare Fund, created from October 2005 for the employees of Pune Municipal Corporation, funded through annual contributions from Class I to IV employees (Rs. 500, Rs. 400, Rs. 300 and Rs. 150 respectively) and an equal share from the Municipal Fund. Through this fund an executive committee implements various welfare schemes for PMC employees, including an heir grant of Rs. 22,500 to heirs of a deceased employee, interest-free education loan scholarships of up to Rs. 25,000 for employees'' children in higher education, sports and cultural activities, felicitation of children scoring 65% or higher in 10th and 12th standard examinations, an Outstanding Worker Award with a cash prize of Rs. 25,000, and the annual Kamgar Dindi procession.', 'Rs. 22,500', 'One-time Direct Bank Transfer (DBT)', 0, 'Within 1 year from the death of the employee (for the heir grant application)', NULL, 'Applicants must be PMC employees who are members of the Labour Welfare Fund', NULL, NULL, NULL, NULL, NULL, NULL, 'https://webadmin.pmc.gov.in/labour-welfare-fund-0', NULL, '["Application in prescribed form/format","Death Certificate of the employee","Payment slip of the employee for the month of April","Photo copy of ration card","Bank Passbook Xerox / photocopy or cancelled cheque","Bonafide Certificate of the Child","Last passing year mark sheet / 10th or 12th passed mark sheet of the child"]'::jsonb, '["1. Application form","Application in prescribed form/format","Death Certificate of the employee","Payment slip of the employee for the month of April","Photo copy of ration card","Bank Passbook Xerox / photocopy or cancelled cheque","Bonafide Certificate of the Child","Last passing year mark sheet / 10th or 12th passed mark sheet of the child"]'::jsonb, NULL, NULL, TRUE, '2026-10-04T10:31:43.407257+00:00', '2026-10-04T10:31:43.407257+00:00', 'EDU_DBT', '{}'::jsonb, '{}'::jsonb, '{}'::jsonb, NULL, 'verified', '2026-10-04T10:58:10.029+00:00', '2da0eb32aca2e7e7bc4231d840b83ad5a6ca8ef273715978bafa12d16b623643', NULL, 'Employee should be a member of Labour Welfare Fund
Employee should not have more than two children
The loan amount is provided only for higher education
The loan amount is the amount of actual fee paid or Rs. 50,000/- whichever is less
Loan amount recovered from employee''s salary in 50 equal instalments without any interest
Heir grant application should be made in prescribed form within 1 year from the death of the employee', NULL, 'offline', NULL, NULL),
  ('13d09761-5163-4e04-8f35-e27a736fb293', 'pmc-model-schools', 'PMC-001', 'Pune Municipal Corporation', 'Bhavan Rachna Department (joint initiative of the Pune Municipal Corporation Education Board and the Building Design Department)', 'EDUCATION', 'education', 'Education', 'PMC_MODEL_SCHOOLS', 'Model School Scheme', '{"mr":"unknown"}'::jsonb, 'The Model School Scheme has been implemented in Pune city from the year 2023-24 as a joint initiative of the Pune Municipal Corporation Education Board and the Building Design Department. Every year, one school from each regional office is selected, making a total of 15 schools. In these selected schools, a uniform color scheme, standardized flooring, toilet design, and Bala painting are being implemented, along with structural repairs (toilets, water tanks, boundary walls, playgrounds, waterproofing, door and window repairs), electrical systems, CCTV setup, fire safety systems, and rainwater harvesting work.', NULL, 'One-time Direct Bank Transfer (DBT)', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://webadmin.pmc.gov.in/model-schools', NULL, '[]'::jsonb, '["1. Application form"]'::jsonb, NULL, NULL, TRUE, '2026-10-04T10:31:37.891378+00:00', '2026-10-04T10:31:37.891378+00:00', 'EDU_DBT', '{}'::jsonb, '{}'::jsonb, '{}'::jsonb, NULL, 'verified', '2026-10-04T10:58:10.029+00:00', 'c5bd5f2eca1854e0b65544101cf752e9afe2d69071b6c59a66e13625f1554bb5', NULL, 'unknown', NULL, NULL, NULL, NULL),
  ('fd2318fd-7b0c-4c2f-8080-26a0aa57cba3', 'pmc-national-health-program', 'PMC-001', 'Pune Municipal Corporation', 'Pune Municipal Corporation Department of Health', 'HEALTHCARE', 'healthcare', 'Healthcare', 'PMC_NATIONAL_HEALTH_PROGRAM', 'National Health Program', '{"mr":"राष्ट्रीय आरोग्य कार्यक्रम"}'::jsonb, 'The Pune Municipal Corporation Health Department implements the National Urban Health Mission (NUHM) in Pune city, running 58 Primary Urban Health Centres, 19 maternity hospitals and other city health facilities. Under this program, schemes such as Janani Suraksha Yojana, Pradhan Mantri Matru Vandana Yojana, Pradhan Mantri Jan Arogya Yojana and the Prime Minister''s Safe Motherhood Mission provide maternity benefits, free health check-ups for pregnant women and health coverage to eligible urban residents, particularly the urban poor and slum populations.', NULL, 'One-time Direct Bank Transfer (DBT)', 0, NULL, NULL, NULL, 800000, NULL, NULL, NULL, NULL, NULL, 'https://webadmin.pmc.gov.in/national-health-program', NULL, '["Aadhaar Card / Enrollment ID (Enrollment Number in MCTS/RCH Portal)","Birth Registration Certificate"]'::jsonb, '["1. Application form","Aadhaar Card / Enrollment ID (Enrollment Number in MCTS/RCH Portal)","Birth Registration Certificate"]'::jsonb, NULL, NULL, TRUE, '2026-10-04T10:32:18.36388+00:00', '2026-10-04T10:32:18.36388+00:00', 'HEALTH', '{}'::jsonb, '{}'::jsonb, '{}'::jsonb, NULL, 'verified', '2026-10-04T10:32:17.942+00:00', '03c58e4fe08814650520ad42d66e9eae4dfac49634e542dc583da0dd0251369c', NULL, 'If a pregnant mother belonging to below poverty line, Scheduled Caste and Scheduled Tribe who is a resident of an urban area gives birth in an urban area, in a government or a private health institution recognized for Janani Suraksha Yojana, the beneficiary under Janani Suraksha Yojana will be paid a benefit of Rs.600/- to the said mother.
First Installment – Rs.3000 – within 6 months from the last date of menstruation. Registration of pregnancies and at least one antenatal check-up is required in a health institution recognized by the state government.
Second Installment – Rs.2000 – Birth Registration Certificate. The child needs to have BCG, OPV, DPT, IVP and Hepatitis-B dose or vaccination (complete the primary vaccination cycle).
It is mandatory to register with Asha, Anganwadi worker, health worker or any government health institution during pregnancy to avail the said scheme.
Aadhaar Card / Enrollment ID (Enrollment Number in MCTS/RCH Portal) is mandatory to avail this scheme.
Women whose net household income is less than Rs.8 lakhs per annum.
Scheduled Caste and Scheduled Tribe women.
Women beneficiaries under Prime Minister Jan Arogya Yojana (PMJAY) under Ayushman Bharat.
Women e-Labour Card holders.
Beneficiaries under Kisan Samman Nidhi, women farmers.
Women holding MGNREGA Job Card.
Pregnant and Lactating Anganwadi Workers (AWW), Anganwadi Helpers (AWHs), ASHA Volunteers (ASHAs).', NULL, 'offline', NULL, NULL),
  ('52036892-226e-4f03-8bb6-a3195779b908', 'pmc-rani-lakshmibai-women', 'PMC-001', 'Pune Municipal Corporation', 'समाज विकास विभाग, पुणे महानगरपालिका', 'EDUCATION', 'education', 'Education', 'PMC_RANI_LAKSHMIBAI_WOMEN', 'Rani Lakshmibai Mahila Sakshamikaran Yojana', '{"mr":"राणी लक्ष्मीबाई महिला सक्षमीकरण योजना"}'::jsonb, 'A women empowerment scheme by Pune Municipal Corporation''s Social Development Department that provides education, training, capacity building and awareness programs for women across different age groups and socio-economic backgrounds in Pune, including lecture series, short-term skill training (LTD), driving training, and guidance for school/college students.', 'Rs. 25,000', 'One-time Direct Bank Transfer (DBT)', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'जावक क्र. सविवि/२३१ दिनांक ०३/०३/२०२१', NULL, NULL, 'https://webadmin.pmc.gov.in/sites/default/files/circular/Rani.pdf', NULL, '["Aadhaar Card"]'::jsonb, '["1. Application form","Aadhaar Card"]'::jsonb, NULL, NULL, TRUE, '2026-10-04T10:42:57.837021+00:00', '2026-10-04T10:42:57.837021+00:00', 'EDU_DBT', '{}'::jsonb, '{}'::jsonb, '{}'::jsonb, NULL, 'verified', '2026-10-04T10:58:10.029+00:00', 'e4f0412a7897ebe165f2cc3bd5b89e4b3908b57561a072e3c88a6c9c4a58007f', NULL, 'उच्च शिक्षित, शिक्षित — सर्व क्षेत्रात कार्यरत महिला वर्ग
