  ('a2222222-2222-2222-2222-222222222222', 'pmc-sathe-class12', 'PMC-001', 'Pune Municipal Corporation', 'PMC Social Development Department (समाज विकास विभाग)', 'EDUCATION', 'education', 'Education Grants', 'PMC-SDD-EDU-2026-02', 'Lokshahir Annabhau Sathe Educational Assistance Scheme', '{"mr":"लोकशाहीर अण्णाभाऊ साठे शैक्षणिक अर्थसहाय्य योजना"}'::jsonb, 'One-time cash assistance grant for Pune students who successfully cleared Class 12 (HSC) and have enrolled into higher degree programs (Engineering, Medical, Commerce, Science, Arts, IT).', 'Rs. 25,000', 'One-time Direct Bank Transfer (DBT)', 25000, 'October 31, 2026', NULL, 'Minimum 75.00% to 80.00% in Class 12 (HSC) depending on stream and category', 250000, 'Under Rs. 2,50,000 per year', 3, 'PMC Resolution No. 1184-C', NULL, NULL, NULL, 'e1111111-1111-1111-1111-111111111111', '["Attested copy of Class 12 (HSC) Marksheet","Degree College Bonafide Certificate or First Term Fee Receipt","Tahsildar Family Income Certificate","Student Bank Passbook Copy","Student Aadhaar Card","Proof of 3 Years Pune Domicile"]'::jsonb, '["1. Printed Application Form (Form 1184-C)","2. Student Aadhaar Card Copy","3. Attested Class 12 Marksheet Copy","4. Degree College Fee Receipt / Bonafide","5. Tahsildar Income Certificate","6. Bank Passbook Copy"]'::jsonb, 'PMC Form 1184-C (HSC Higher Education Grant)', 'https://dbt.pmc.gov.in/forms/annabhau_sathe_hsc.pdf', TRUE, '2026-10-03T18:37:54.615387+00:00', '2026-10-03T18:37:54.615387+00:00', 'EDU_DBT', '{"en":"Lokshahir Annabhau Sathe Educational Assistance Scheme","mr":"लोकशाहीर अण्णाभाऊ साठे शैक्षणिक अर्थसहाय्य योजना"}'::jsonb, '{}'::jsonb, '{}'::jsonb, NULL, 'verified', '2026-10-04T10:58:10.029+00:00', NULL, NULL, 'Passed Class 12 (HSC) and admitted to a degree course.
