  ('a6666666-6666-6666-6666-666666666666', 'pmc-savitribai-girls', 'PMC-001', 'Pune Municipal Corporation', 'PMC Social Development Department (समाज विकास विभाग)', 'EDUCATION', 'education', 'Education Grants', 'PMC-SDD-EDU-2026-03', 'Krantijyoti Savitribai Phule Scheme for Girl Students', '{"mr":"क्रांतिज्योती सावित्रीबाई फुले कन्या शिक्षण सहाय्य योजना"}'::jsonb, 'Financial assistance toward technical training, nursing diplomas, and computer certification fees for female students residing in Pune municipal corporation wards.', 'Rs. 10,000 to Rs. 20,000', 'Vocational & Technical Course Fee Reimbursement', 20000, 'October 31, 2026', NULL, 'Girl students pursuing ITI, Polytechnic, Nursing, or Computer Diploma', 250000, 'Under Rs. 2,50,000 per year (Waived for orphans)', 3, 'PMC Resolution No. 902-D', NULL, NULL, NULL, 'e1111111-1111-1111-1111-111111111111', '["Admission Fee Receipt from accredited Technical / ITI Institute","Class 10 or 12 Marksheet Copy","Tahsildar Income Certificate","Student Bank Passbook Copy","Student Aadhaar Card"]'::jsonb, '["1. Savitribai Phule Scheme Application Form","2. Student Aadhaar Card Copy","3. Technical Institute Fee Receipt","4. Marksheet Copy","5. Income Certificate","6. Bank Passbook"]'::jsonb, 'PMC Savitribai Phule Technical Grant Form', 'https://dbt.pmc.gov.in/forms/savitribai_phule_girls.pdf', TRUE, '2026-10-03T22:07:29.407244+00:00', '2026-10-03T22:07:29.407244+00:00', 'EDU_DBT', '{"en":"Krantijyoti Savitribai Phule Scheme for Girl Students","mr":"क्रांतिज्योती सावित्रीबाई फुले कन्या शिक्षण सहाय्य योजना"}'::jsonb, '{}'::jsonb, '{}'::jsonb, NULL, 'verified', '2026-10-04T10:58:10.029+00:00', NULL, NULL, 'Girl student enrolled in an ITI, polytechnic, nursing or computer diploma course.
