  ('74af37e7-ea3f-4d45-855d-35c72a575f5a', 'pmc-secondary-school-initiatives', 'PMC-001', 'Pune Municipal Corporation', 'Secondary and Technical Education', 'EDUCATION', 'education', 'Education', 'PMC_SECONDARY_SCHOOL_INITIATIVES', 'Special Initiatives for Students of Pune Municipal Corporation-Run Secondary Schools', '{"mr":"unknown"}'::jsonb, 'A set of welfare initiatives by the Pune Municipal Corporation for students in its secondary schools, including free textbooks, two free uniforms via DBT, subsidised and fully-funded bus passes, a free set of 21 expected question papers for Grade 10, the Sharadabai Pawar Scholarship of ₹51,000 for high-scoring board exam students, free sanitary napkins for girls aged 11 to 19, snacks on national holidays, educational excursions, free answer sheets, and payment of SSC and HSC board exam fees.', 'Rs. 51,000', 'One-time Direct Bank Transfer (DBT)', 0, NULL, NULL, 'Grade 10 and 12 students in PMC-run secondary schools scoring above 85% and 80% respectively in board exams receive the Sharadabai Pawar Scholarship of ₹51,000', NULL, NULL, NULL, NULL, NULL, NULL, 'https://webadmin.pmc.gov.in/special-initiatives-students-pune-municipal-corporation-run-secondary-schools', NULL, '["Student''s/parents'' bank account (for DBT transfers)"]'::jsonb, '["1. Application form","Student''s/parents'' bank account (for DBT transfers)"]'::jsonb, NULL, NULL, TRUE, '2026-10-04T10:32:13.635202+00:00', '2026-10-04T10:32:13.635202+00:00', 'EDU_DBT', '{}'::jsonb, '{}'::jsonb, '{}'::jsonb, NULL, 'verified', '2026-10-04T10:32:12.656+00:00', 'bcd437c071b02e5d9158aa1f8666d99e55d2bee9e53e1a8dc043e54c85e61ce4', NULL, 'Students of Pune Municipal Corporation-run secondary schools
Students of night schools (Grades 9 and 10) within PMC limits
Students in Grade 5 to Grade 10 residing within PMC limits
Grade 10 and 12 students in PMC-run secondary schools who score above 85% and 80% respectively in the board exams
Girls aged 11 to 19 in PMC-run primary and secondary schools', NULL, NULL, NULL, NULL),
  ('a3333333-3333-3333-3333-333333333333', 'pmc-sgay-health', 'PMC-001', 'Pune Municipal Corporation', 'Health Department, Pune Municipal Corporation', 'HEALTHCARE', 'healthcare', 'Healthcare', 'PMC_SGAY_HEALTH', 'Urban Poor Health Scheme', '{"mr":"शहरी गरीब वैद्यकीय सहाय्य योजना"}'::jsonb, 'PMC''s Urban Poor Health Scheme provides a health card to citizens living in PMC jurisdiction who register with the Health Department. Members get free treatment and medicines at PMC dispensaries, and for IPD treatment in General Ward at paneled private hospitals, PMC pays 50% of the final bill (up to Rs 1,00,000 per family per financial year). Cancer and dialysis patients can get 100% discount on bills up to Rs 2,00,000. Membership costs Rs 200 per financial year and must be renewed annually.', 'Rs. 1,00,000', '50% Treatment Concession & Hospital Assistance', 100000, 'Wed, 05/20/2026 - 10:39', NULL, 'Maximum amount of Rs.1,00,000 per family per financial year for IPD treatments in paneled private hospitals', 100000, 'Under Rs. 1,60,000 per year', 3, 'PMC Resolution No. GB/2010/CR-42', NULL, NULL, 'https://webadmin.pmc.gov.in/urban-poor-health-scheme', 'e2222222-2222-2222-2222-222222222222', '["Income Certificate up to 1 lakh from Tahsildar Office (current financial year)","Xerox copy of Below Poverty Line, Yellow Ration Card","Slum rehabilitation department, PMC- service tax receipt (for citizens living in slum area)","Xerox copy of Ration Card","Xerox copies of Birth Certificate of members children","Family members combined photograph (visiting card size) - 2 copies"]'::jsonb, '["1. Application form","Income Certificate up to 1 lakh from Tahsildar Office (current financial year)","Xerox copy of Below Poverty Line, Yellow Ration Card","Slum rehabilitation department, PMC- service tax receipt (for citizens living in slum area)","Xerox copy of Ration Card","Xerox copies of Birth Certificate of members children","Family members combined photograph (visiting card size) - 2 copies"]'::jsonb, 'Urban Poor Health Scheme form', 'https://sgy.pmc.gov.in/forms/sgay_registration.pdf', TRUE, '2026-10-03T18:37:54.615387+00:00', '2026-10-03T18:37:54.615387+00:00', 'HEALTH', '{"en":"Shahari Garib Arogya Yojana (SGAY)","mr":"शहरी गरीब आरोग्य योजना (वैद्यकीय उपचार सवलत)"}'::jsonb, '{}'::jsonb, '{}'::jsonb, NULL, 'verified', '2026-10-04T10:58:10.029+00:00', 'fa403b8fb582843dd5cbfaf73b87c029579b4336c6540d676acbe2a120078051', NULL, 'Citizens living in jurisdiction of Pune Municipal Corporation, who are willing to take membership of Urban Poor scheme are supposed to fill the Urban Poor Health Scheme form from Health Department, PMC and submit the attested xerox copy of one document out of following three documents
For current financial year, Income Certificate up to 1 lacks from Tahsildar Office OR Xerox copy of Below Poverty Line, Yellow Ration Card OR Citizens living in slum area having slum rehabilitation department, PMC- service tax receipt
Citizens of Pune who could get the benefit from any other Government, Semi government /Health Insurance Company, can not get enrolled under Urban Poor Health Scheme of PMC Health Department
Urban Poor Health Scheme, is applicable to only General Ward. Patients getting admitted in semi-private, private or deluxe room can not get benefit of this scheme
Urban Poor Health Scheme Card covers member''s wife/husband, Mother and Father of member, and only first two children of member age less than 25 years
If the third child of the member is born before 01/01/2005, then his/her name gets enrolled in the Urban Poor Card
If any one got married before 25 years of his/her age, then his/her name gets canceled from Urban Poor Card
Urban Poor card is valid for one financial year. Every Financial Year, citizens have to renew the membership. Members do not get benefits of Urban Poor Health Scheme on previous years membership', NULL, 'offline', 'https://sgy.pmc.gov.in/', NULL),
  ('58a42f38-3504-40a1-b2f5-b4b9eb666854', 'pmc-shetkari-karjamukti', 'PMC-001', 'Pune Municipal Corporation', 'मुख्य लेखा व वित्त विभाग, पुणे महानगरपालिका', 'AGRICULTURE_LIVELIHOOD', 'livelihood', 'Livelihood & Self-Employment', 'PMC_SHETKARI_KARJAMUKTI', 'Punyashlok Ahilyadevi Holkar Shetkari Karjamukti Yojana 2026', '{"mr":"पुण्यश्लोक अहिल्यादेवी होळकर शेतकरी कर्जमुक्ती योजना २०६"}'::jsonb, 'A farmer loan waiver scheme providing debt relief up to Rs. 2,00,000 to eligible farmers of Maharashtra, with an additional benefit of up to Rs. 50,000 for farmers who make regular loan repayments. Members of urban local self-government bodies and officers/employees drawing gross monthly salary above Rs. 25,000 are excluded from the scheme.', 'Rs. 2,00,000', 'One-time Direct Bank Transfer (DBT)', 0, NULL, NULL, 'पात्र शेतकऱ्यांना रु. २,००,००० पर्यंत कर्ज मुक्ती; नियमित परतफेड करणाऱ्या शेतकऱ्यांना रु. ५०,००० पर्यंत अतिरिक्त लाभ', NULL, NULL, NULL, NULL, NULL, NULL, 'https://webadmin.pmc.gov.in/sites/default/files/circular/Ahilyabai%20holkar%20yojana.pdf', NULL, '["Aadhaar Card"]'::jsonb, '["1. Application form","Aadhaar Card"]'::jsonb, NULL, NULL, TRUE, '2026-10-04T10:45:14.582755+00:00', '2026-10-04T10:45:14.582755+00:00', 'EDU_DBT', '{}'::jsonb, '{}'::jsonb, '{}'::jsonb, NULL, 'verified', '2026-10-04T10:58:10.029+00:00', 'd777ced5ff3e5da3152f75a49c80be2468d8e478eb67c0dc585cc20e3efde911', NULL, 'राज्यातील पात्र शेतकऱ्यांना रु. २,००,०० पर्यंत कर्ज मुक्तीचा लाभ देण्यात येणार आहे.
नियमित परतफेड करणाऱ्या शेतकऱ्यांना रु. ५० हजार इतक्या अधिकतम रकमेपर्यंत लाभ देण्यात येणार आहे.
नागरी स्थानिक स्वराज्य संस्थांचे सदस्य (महानगरपालिका, नगरपालिका व नगरपंचायत नगरसेवक) सदर योजनेचा लाभ घेण्यास पात्र असणार नाहीत.
रु. २,००० पेक्षा जास्त एकत्रित मासिक वेतन घेणारे अधिकारी/कर्मचारी सदर योजनेचा लाभ घेण्यास पात्र असणार नाहीत.', NULL, 'offline', NULL, NULL),
  ('df8a7a82-c0ab-43c3-b3cd-2afae6724606', 'pmc-sports-academy', 'PMC-001', 'Pune Municipal Corporation', 'Sports Department', 'EDUCATION', 'education', 'Education', 'PMC_SPORTS_ACADEMY', 'Non-resident Sports Academy', '{"mr":"unknown"}'::jsonb, 'Pune Municipal Corporation''s education department has established non-resident sports academies in the city, including Khashaba Jadhav Sports Academy at Sinhagad Road, Bharat Ratna Sachin Tendulkar Sports Academy at Hadapsar, and a Sports Academy School at Yerawada. These academies provide sports facilities and technical training in sports such as Kabaddi, Kho-Kho, Mallakhamb, Yoga, Kusti, Basketball, Volleyball, Handball, Throwball, and Athletics. PMC aims to introduce at least one non-resident sports academy in each zone of the regional commissioner, and also runs a Sports Skills Proficiency Test and plans Sports Nurseries for children aged 3 to 12 years.', NULL, 'One-time Direct Bank Transfer (DBT)', 0, NULL, NULL, 'Pune Municipal Corporation school students studying in class III are eligible for admission to the sports academy.', NULL, NULL, 5, NULL, NULL, NULL, 'https://webadmin.pmc.gov.in/non-resident-sports-academy', NULL, '["List of students recommended by the School Principal to the Sports Department","Medical examination conducted by the Health Officer"]'::jsonb, '["1. Application form","List of students recommended by the School Principal to the Sports Department","Medical examination conducted by the Health Officer"]'::jsonb, NULL, NULL, TRUE, '2026-10-04T10:31:42.358227+00:00', '2026-10-04T10:31:42.358227+00:00', 'EDU_DBT', '{}'::jsonb, '{}'::jsonb, '{}'::jsonb, NULL, 'verified', '2026-10-04T10:58:10.029+00:00', '35b4fbf72ba571bf2c99db0ef1fa31f07a28686e39bd2ef520d529ce76885bc7', NULL, 'As many as 25 budding players from municipal and private schools shall be eligible to take admission to the academy.
The School Principal should recommend the list of students to the Sports Department.
These students should be staying in Pune with their parents for at least five years.
Pune Municipal Corporation school students studying in class III will be eligible to take admission in the sports academy.
They must be studying in the same school from class I.
At the end of the academic year of class III, a physical fitness test will be conducted at the divisional level.
All students have to undergo a medical examination conducted by the Health Officer. Students passing this test will be eligible for admission.
Students whose age is from 3 years to 12 years can participate in sports nursery.', NULL, NULL, NULL, NULL),
  ('c529757b-9fa5-4668-8c0f-2dc5efc627d8', 'pmc-sports-material-grant', 'PMC-001', 'Pune Municipal Corporation', 'Sports Department, Pune Municipal Corporation', 'EDUCATION', 'education', 'Education', 'PMC_SPORTS_MATERIAL_GRANT', 'Grant for purchase of Sports Material', '{"mr":"unknown"}'::jsonb, 'In accordance with the policy of the Government of Maharashtra, Pune Municipal Corporation provides grants to approved government and private sports institutions under the District Sports Officer for the purchase of sports equipment, construction of gyms, and upgrading existing gyms, aiming to promote daily practice, sports competitions, training, and a love for sports among students in Pune city. The grant amount is decided with the approval of the Sports Committee. For the financial year 2024-2025, a provision of Rs. 1,50,00,000/- has been made, including allocations to named sports complexes and for sports nursery equipment.', 'Rs. 1,50,00,000', 'One-time Direct Bank Transfer (DBT)', 0, NULL, NULL, 'Selection of the eligible institution will remain solely with the Sports Committee.', NULL, NULL, NULL, NULL, NULL, NULL, 'https://webadmin.pmc.gov.in/grant-purchase-sports-material', NULL, '[]'::jsonb, '["1. Application form"]'::jsonb, NULL, NULL, TRUE, '2026-10-04T10:32:15.397241+00:00', '2026-10-04T10:32:15.397241+00:00', 'EDU_DBT', '{}'::jsonb, '{}'::jsonb, '{}'::jsonb, NULL, 'verified', '2026-10-04T10:58:10.029+00:00', 'd36b420aee069504ea5570f10ddb7404140b582e07d75caf1d5bae9bad0e61bd', NULL, 'Grants are provided to approved government and private sports institutions under the District Sports Officer.
The decision of which institution is eligible or the selection of the institution will remain solely with the Sports Committee.
The decision to grant funds will depend on the financial condition of the concerned institution, according to the prevailing policy of Pune Municipal Corporation.', NULL, NULL, NULL, NULL),
  ('a5555555-5555-5555-5555-555555555555', 'pmc-svanidhi-hawker', 'PMC-001', 'Pune Municipal Corporation', 'Ministry of Housing & Urban Affairs (MoHUA), Government of India', 'AGRICULTURE_LIVELIHOOD', 'livelihood', 'Livelihood & Self-Employment', 'PMC_SVANIDHI_HAWKER', 'Pradhan Mantri Street Vendor''s AtmaNirbhar Nidhi (PM SVANidhi) Scheme', '{"mr":"unknown"}'::jsonb, 'PM SVANidhi is a Central Sector micro-credit scheme for urban street vendors, first launched in June 2020, that provides collateral-free working capital term loans in three tranches (up to ₹15,000, ₹25,000 and ₹50,000), a 7% per annum interest subsidy, a UPI-linked RuPay credit card, and cashback incentives for digital transactions. It also supports vendor recognition, digital adoption, capacity building and linkage to social security schemes. The lending period has been extended till March 31, 2030.', 'Rs. 15,000', 'Collateral-free Working Capital Micro-Credit with 7% Interest Subsidy', 50000, 'Lending period of loans extended till March 31, 2030', NULL, 'Street vendors identified via Certificate of Vending/Identity Card/Letter of Recommendation issued by TVC/ULBs (statutory towns) or Block Development Offices (census towns and peri-urban areas)', 200000, 'Under Rs. 2,00,000 per year', 1, 'MoHUA / PMC Urban Livelihood Resolution 2024', NULL, NULL, 'https://www.mohua.gov.in/static/uploads/2026/01/bde957bc3a87fb001c05ddd09484edda.pdf', 'e4444444-4444-4444-4444-444444444444', '["Certificate of Vending (CoV)","Identity Card","Letter of Recommendation (LoR)"]'::jsonb, '["1. Application form","Certificate of Vending (CoV)","Identity Card","Letter of Recommendation (LoR)"]'::jsonb, 'PM SVANidhi Urban Vendor Form', 'https://pmsvanidhi.mohua.gov.in/forms/vendor_application.pdf', TRUE, '2026-10-03T18:37:54.615387+00:00', '2026-10-03T18:37:54.615387+00:00', 'EDU_DBT', '{"en":"PM SVANidhi Urban Farm Produce & Vegetable Vendor Scheme","mr":"पीएम स्वनिधी भाजीपाला व शेतमाल विक्रेते कर्ज योजना"}'::jsonb, '{}'::jsonb, '{}'::jsonb, NULL, 'verified', '2026-10-04T10:58:10.029+00:00', 'c61fe6864b89db3121d9a27e7cf159bc75f395deba83788375abe7e0d38a51b4', NULL, 'The target beneficiaries of the scheme are street vendors vending in various city-regions.
In statutory towns, the Certificate of Vending (CoV)/Identity Card/Letter of Recommendation (LoR) to the street vendors will be issued by TVC/ ULBs.
For census towns and peri urban areas, the Letter of Recommendation (LoR) to the street vendors will be issued by Block Development Offices after due verification as per Annexure A.
''Street Vendor'' shall be engaged in vending activity aligning to the definition mentioned in Street Vendors (Protection of Livelihood and Regulation of Street Vending) Act, 2014.
The vendor may be engaged in either seasonal or year-round vending activities.
The vendor may operate as a mobile or stationary vendor.
The vendor should be vending in the respective census town or peri-urban areas.', NULL, 'online', 'https://pmsvanidhi.qcin.org/account/landing-page', NULL),
  ('5fda4f70-e369-4898-9bcc-4517866e7835', 'pmc-vocational-training', 'PMC-001', 'Pune Municipal Corporation', 'Social Development Department, Pune Municipal Corporation', 'AGRICULTURE_LIVELIHOOD', 'livelihood', 'Livelihood & Self-Employment', 'PMC_VOCATIONAL_TRAINING', 'Vocational Training Centres', '{"mr":"unknown"}'::jsonb, 'The Social Development Department of the Pune Municipal Corporation runs Vocational Training Centres in Pune, along with training institutes run in collaboration with various organizations, and sales centres to provide a good market for products manufactured by self-help groups.', NULL, 'One-time Direct Bank Transfer (DBT)', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://webadmin.pmc.gov.in/vocational-training-centres', NULL, '[]'::jsonb, '["1. Application form"]'::jsonb, NULL, NULL, TRUE, '2026-10-04T10:32:56.696434+00:00', '2026-10-04T10:32:56.696434+00:00', 'EDU_DBT', '{}'::jsonb, '{}'::jsonb, '{}'::jsonb, NULL, 'verified', '2026-10-04T10:58:10.029+00:00', '8b70bab370c3e8a6aea33cdda01fa2d3e3ef05bc670699bcc23a456b17331557', NULL, 'unknown', NULL, NULL, NULL, NULL),
